import { Accessor, createContext, createMemo, useContext } from "solid-js";

import { AgeSelectModel } from "#core/ui-next/screens/create-game/age-select-model.js";
import { CivSelectModel } from "#core/ui-next/screens/create-game/civ-select-model.js";
import { ModelLifecycle, ModelRegistry } from "#core/ui-next/services/model-registry.js";

export interface TotModel {
	isTotEnabled: Accessor<boolean>;
	isHeightOfPower: Accessor<boolean>;
}

export function createTotModel(): TotModel {
	const ageModel = AgeSelectModel.get();
	const civModel = CivSelectModel.get();

	const isTotEnabled = createMemo(() => ageModel.selectedAge.type != civModel.selectedCiv()?.apexAge);
	const isHeightOfPower = createMemo(() => ageModel.selectedAge.type == civModel.selectedCiv()?.apexAge);

	return { isTotEnabled, isHeightOfPower };
}

export const TotModel = ModelRegistry.register("TotModel", ModelLifecycle.SharedInstance, createTotModel);

export const TotModelContext = createContext<TotModel>();

export function useTotModelContext() {
	const context = useContext(TotModelContext);

	if (!context) {
		throw new Error("useTotModelContext: Cannot find context!");
	}

	return context;
}
